public class FastDateFormat_format_TriageGen3Test {

    @Test
    public void testFormat_WithTimeZoneForcedTrue() {
        // Arrange
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone utc = TimeZone.getTimeZone("UTC");
        TimeZone pst = TimeZone.getTimeZone("America/Los_Angeles");

        // Using getInstance(pattern, timeZone) sets mTimeZoneForced to true internally
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, utc);

        Calendar calendar = Calendar.getInstance(pst);
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // Act
        // Since mTimeZoneForced is true, the method should clone the calendar 
        // and force the UTC timezone regardless of the input calendar's timezone.
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        // 10:00 AM PST is 17:00 UTC (PST is UTC-8)
        String expected = "2023-10-27 17:00:00";
        assertEquals(expected, result.toString());

        // Verify the original calendar timezone was not mutated (calendar.clone() was used)
        assertEquals("America/Los_Angeles", calendar.getTimeZone().getID());
    }

    @Test
    public void testFormat_WithTimeZoneForcedFalse() {
        // Arrange
        String pattern = "yyyy-MM-dd HH:mm:ss";
        // getInstance(pattern) uses the system default timezone and mTimeZoneForced is false
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        TimeZone pst = TimeZone.getTimeZone("America/Los_Angeles");
        Calendar calendar = Calendar.getInstance(pst);
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();

        // Act
        // Since mTimeZoneForced is false, it should use the calendar's own timezone
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        String expected = "2023-10-27 10:00:00";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testFormat_WithBufferContent() {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        calendar.set(2025, Calendar.JANUARY, 1);

        StringBuffer buf = new StringBuffer("Prefix: ");

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        // The method should append to the existing buffer
        assertEquals("Prefix: 2025", result.toString());
    }

    @Test
    public void testFormat_WithDifferentLocale() {
        // Arrange
        // Using a locale that formats months/days differently (e.g., French)
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.MAY, 1);

        StringBuffer buf = new StringBuffer();

        // Act
        StringBuffer result = fdf.format(calendar, buf);

        // Assert
        assertEquals("mai", result.toString());
    }
}
